-- 素材标签体系 v2 备份表导出
-- 生成于 2026-07-24，DROP 前的回滚闭包
-- 回灌：mysql -u<user> -p commission_db < 本文件

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;


-- ===== ark_asset_tags_bak_taxv2 =====
DROP TABLE IF EXISTS `ark_asset_tags_bak_taxv2`;
CREATE TABLE `ark_asset_tags_bak_taxv2` (
  `asset_id` int unsigned NOT NULL COMMENT '素材ID',
  `version_id` int unsigned DEFAULT NULL COMMENT '打标时对应的素材版本ID(可空)',
  `dimension_id` int unsigned NOT NULL COMMENT '标签维度ID',
  `tag_value_id` int unsigned NOT NULL COMMENT '标签值ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ===== ark_asset_tags_bak_retire =====
DROP TABLE IF EXISTS `ark_asset_tags_bak_retire`;
CREATE TABLE `ark_asset_tags_bak_retire` (
  `asset_id` int unsigned NOT NULL COMMENT '素材ID',
  `version_id` int unsigned DEFAULT NULL COMMENT '打标时对应的素材版本ID(可空)',
  `dimension_id` int unsigned NOT NULL COMMENT '标签维度ID',
  `tag_value_id` int unsigned NOT NULL COMMENT '标签值ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ===== ark_tag_values_bak_retire =====
DROP TABLE IF EXISTS `ark_tag_values_bak_retire`;
CREATE TABLE `ark_tag_values_bak_retire` (
  `id` int unsigned NOT NULL DEFAULT '0' COMMENT '主键',
  `dimension_id` int unsigned NOT NULL COMMENT '所属标签维度ID',
  `value` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标签值',
  `color_hex` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '颜色值,支持hex或rgb格式',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序权重',
  `is_active` smallint NOT NULL DEFAULT '1' COMMENT '0=禁用,1=启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `image_path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签图片路径',
  `name_en` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '英文名(agent 检索用)',
  `aliases` json DEFAULT NULL COMMENT '别名数组(中英混合,agent 模糊匹配用)',
  `parent_value_id` int unsigned DEFAULT NULL COMMENT '父级标签值ID(内容子类→内容大类挂靠,仅该组维度使用)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ===== ark_tag_dimensions_bak_retire =====
DROP TABLE IF EXISTS `ark_tag_dimensions_bak_retire`;
CREATE TABLE `ark_tag_dimensions_bak_retire` (
  `id` int unsigned NOT NULL DEFAULT '0' COMMENT '主键',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '维度标识(英文)',
  `label` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '维度显示名(中文)',
  `is_single_select` smallint NOT NULL DEFAULT '0' COMMENT '0=多选,1=单选',
  `is_system` smallint NOT NULL DEFAULT '0' COMMENT '0=自定义,1=系统内置',
  `is_required` smallint NOT NULL DEFAULT '0' COMMENT '0=选填,1=必填',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序权重',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `is_visible` smallint NOT NULL DEFAULT '1' COMMENT '0=隐藏(前端筛选/上传/folder_upload匹配均不参与),1=可见',
  `is_managed` smallint NOT NULL DEFAULT '0' COMMENT '1=系统托管维度,值由派生脚本写入,禁人工增删改'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS=1;
